INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einem Bit?', 2, '[{"text": "Kleinste Informationseinheit", "correct": true, "because": "0 oder 1"}, {"text": "Speicherblock", "correct": false, "because": "Anderes Konzept"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Bits?', 3, '[{"text": "Daten digital darstellen", "correct": true, "because": "Basis der Informatik"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werte kann ein Bit annehmen?', 5, '[{"text": "0", "correct": true, "because": "Binärwert"}, {"text": "1", "correct": true, "because": "Binärwert"}, {"text": "2", "correct": false, "because": "Kein Bit-Wert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Bit hat zwei Zustände. b) Es entspricht 8 Bytes.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "8 Bits = 1 Byte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Bits?', 4, '[{"text": "Binärdarstellung", "correct": false, "because": "Grundlage"}, {"text": "Bitweise Operationen", "correct": false, "because": "Wichtig für Verarbeitung"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 8 Bits ein Byte ergeben?', 2, '[{"text": "Ja", "correct": true, "because": "Standarddefinition"}, {"text": "Nein", "correct": false, "because": "Korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operation wird auf Bits angewendet?', 3, '[{"text": "Bitweise UND (AND)", "correct": true, "because": "Logische Verknüpfung"}, {"text": "Addition (+)", "correct": false, "because": "Für Zahlen"}, {"text": "Formatierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verwendung von Bits?', 5, '[{"text": "Binäre Darstellung", "correct": true, "because": "0 und 1"}, {"text": "Bitoperationen", "correct": true, "because": "z.B. AND, OR"}, {"text": "Textformatierung", "correct": false, "because": "Kein Bit-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Bit ist die Basis für Bytes. b) Es wird nur in Datenbanken genutzt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überall in IT"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Bit unwichtig?', 4, '[{"text": "Wert (0 oder 1)", "correct": false, "because": "Grundlage"}, {"text": "Position", "correct": false, "because": "Für Bedeutung wichtig"}, {"text": "Farbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Bit mehrere Werte gleichzeitig haben?', 2, '[{"text": "Nein", "correct": true, "because": "Nur 0 oder 1"}, {"text": "Ja", "correct": false, "because": "Binär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Arbeit mit Bits?', 4, '[{"text": "Effiziente Speicherung", "correct": true, "because": "Kompakte Daten"}, {"text": "Schnelle Verarbeitung", "correct": true, "because": "Bitoperationen"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Bit nur in der Hardware relevant ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Arbeit mit Bits?', 3, '[{"text": "Korrekte Darstellung", "correct": true, "because": "Datenintegrität"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Bit kann mit AND verknüpft werden. b) Es entspricht einem Byte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Byte = 8 Bits"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein falsch verarbeitetes Bit?', 5, '[{"text": "Datenfehler", "correct": true, "because": "Falsche Werte"}, {"text": "Systemabsturz", "correct": true, "because": "Kritische Operationen"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Bits?', 3, '[{"text": "Bitweise Operationen implementieren", "correct": true, "because": "Programmierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Bit in einem Binär-Stream verarbeitet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Datenfluss"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operation ergibt 0b1010 AND 0b1100?', 4, '[{"text": "0b1000", "correct": true, "because": "Bitweise UND"}, {"text": "0b1110", "correct": false, "because": "OR-Ergebnis"}, {"text": "0b1010", "correct": false, "because": "Falsch"}]');
